 font-weight: 900;
 padding: 6px 16px;
 border-radius: 999px;
 font-size: 0.98rem;
 border: 2px solid var(--ia-blanco);
}

/* Barra de compañero narrativo (Leo + Especialista de nivel) */
.ia-character-coach {
 display: flex;
 align-items: center;
 gap: 14px;
 background: var(--ia-amarillo-soft);
