 letter-spacing: 0.4px;
 display: block;
}

.ia-coach-text {
 font-size: 1.14rem;
 font-weight: 800;
 color: var(--ia-petroleo-dark);
 margin: 2px 0 0;
}

.ia-game-prompt {
 font-size: 1.22rem;
 font-weight: 900;
 color: var(--ia-petroleo-dark);
