}

.ia-reward-icon {
 font-size: 2.6rem;
 margin-bottom: 8px;
}

.ia-reward-name {
 font-size: 1.18rem;
 font-weight: 900;
 color: var(--ia-petroleo);
 margin: 0 0 6px;
}

.ia-reward-status {
 font-size: 0.98rem;
 font-weight: 800;
 color: var(--ia-texto);
}

