    <div class="ia-coach-bubble">
      <span class="ia-coach-name">Leo y Maya · Zona de Palancas</span>
      <p class="ia-coach-text">Maya y yo necesitamos levantar esta caja de 100 kg. ¡Elige una opción y pulsa PROBAR!</p>
    </div>
  </div>
  <div class="ia-game-prompt">¿Qué posición del punto de apoyo permite levantar la carga con menor esfuerzo si aplicamos la fuerza en el extremo contrario?</div>
  <div class="ia-game-stage" id="palanca-stage">
    <svg viewBox="0 0 720 265" width="720" height="265" role="img" aria-label="Escenario interactivo de la palanca con caja pesada a la izquierda, barra rígida y punto de apoyo triangular móvil.">
      <rect width="720" height="265" rx="16" fill="#FFF8E9"/>
      <line x1="40" y1="234" x2="680" y2="234" stroke="#173B57" stroke-width="6" stroke-linecap="round"/>
      <circle cx="235" cy="246" r="5" fill="#39B8AE"/>
      <circle cx="360" cy="246" r="5" fill="#39B8AE"/>
      <circle cx="485" cy="246" r="5" fill="#39B8AE"/>
      <g class="palanca-fulcrum-group">
        <polygon points="360,175 330,234 390,234" fill="#39B8AE" stroke="#173B57" stroke-width="4"/>
        <circle cx="360" cy="175" r="6" fill="#FFC857" stroke="#173B57" stroke-width="2"/>
        <text x="360" y="258" text-anchor="middle" fill="#173B57" font-family="sans-serif" font-size="13" font-weight="bold">PUNTO DE APOYO</text>
      </g>
      <g class="palanca-beam-group">
        <line x1="105" y1="172" x2="615" y2="172" stroke="#173B57" stroke-width="14" stroke-linecap="round"/>
        <g class="palanca-box-group">
          <rect x="112" y="88" width="88" height="78" rx="10" fill="#F28C45" stroke="#173B57" stroke-width="4"/>
          <rect x="126" y="114" width="60" height="26" rx="5" fill="#FFF8E9"/>
          <text x="156" y="132" text-anchor="middle" fill="#173B57" font-family="sans-serif" font-size="14" font-weight="bold">CARGA</text>
        </g>
        <g class="palanca-effort-group">
          <line x1="565" y1="88" x2="565" y2="146" stroke="#FFC857" stroke-width="10" stroke-linecap="round"/>
          <polygon points="565,162 545,136 585,136" fill="#FFC857" stroke="#173B57" stroke-width="3"/>
          <text x="565" y="74" text-anchor="middle" fill="#173B57" font-family="sans-serif" font-size="14" font-weight="bold">FUERZA</text>
        </g>
      </g>
    </svg>
  </div>
  <div class="ia-options-grid" role="group" aria-label="Opciones del reto de palancas">
    <button type="button" class="ia-option-btn" data-opt-index="0" aria-pressed="false">Cerca de la carga.</button>
    <button type="button" class="ia-option-btn" data-opt-index="1" aria-pressed="false">En el centro de la barra.</button>
    <button type="button" class="ia-option-btn" data-opt-index="2" aria-pressed="false">Lejos de la carga.</button>
  </div>
  <div class="ia-game-actions">
    <button type="button" class="ia-btn ia-btn--primary" id="btn-palanca-probar">PROBAR</button>
    <button type="button" class="ia-btn ia-btn--secondary" id="btn-palanca-reintentar">REINTENTAR</button>
    <button type="button" class="ia-btn ia-btn--warning" id="btn-palanca-siguiente" disabled>SIGUIENTE RETO</button>
  </div>
  <div id="palanca-feedback" aria-live="polite"></div>
</div>
</div>
<script>
/* ==========================================================================
   INVENTORES EN ACCIÓN: EL MUNDO DE LAS MÁQUINAS SIMPLES
   Motor interactivo modular:
   - 3 Juegos HTML/CSS/JS independientes + Misión Final paso a paso
   - Personaje guía Leo con 4 expresiones dinámicas + Maya, Bruno y Nora
   - Reproductor de audio accesible con verificación estricta de voz en español
   - Sistema de estrellas (sin duplicados) e insignias persistentes
   ========================================================================== */

(function () {
  'use strict';

  var STORAGE_KEY = 'inventores_en_accion_state_v5';

  function getDefaultState() {
    return {
      stars: {},
      badges: {
        palancas: false,
        poleas: false,
        engranajes: false
      },
      diagnosticoDone: false,
      finalMissionScore: 0,
      finalMissionCompleted: false
    };
  }

  /* ==========================================================================
     RETRATO EXPRESIVO DE LEO (4 EXPRESIONES: descubrimiento, exito, error, felicitacion)
     ========================================================================== */
  function getLeoAvatarSvg(expression) {
    var mouthPath = 'M 24 44 Q 32 50 40 44';
    var eyeRadius = 3;
    var badgeColor = '#39B8AE';

    if (expression === 'exito') {
      mouthPath = 'M 22 42 Q 32 54 42 42 Z';
      badgeColor = '#39B8AE';
    } else if (expression === 'error') {
      mouthPath = 'M 25 46 Q 32 42 39 46';
      badgeColor = '#F28C45';
    } else if (expression === 'felicitacion') {
      mouthPath = 'M 20 41 Q 32 56 44 41 Z';
      eyeRadius = 3.5;
      badgeColor = '#FFC857';
    }

    return (
      '<svg viewBox="0 0 64 64" width="58" height="58" role="img" aria-label="Leo el inventor (' + expression + ')">' +
        '<circle cx="32" cy="32" r="30" fill="' + badgeColor + '" opacity="0.22"/>' +
        '<circle cx="32" cy="36" r="20" fill="#FFE0B2" stroke="#173B57" stroke-width="2.5"/>' +
        '<path d="M 12 30 Q 18 10 36 12 Q 52 14 52 30 Z" fill="#173B57"/>' +
        '<rect x="13" y="18" width="38" height="12" rx="6" fill="#FFC857" stroke="#173B57" stroke-width="2"/>' +
        '<circle cx="24" cy="24" r="6" fill="#39B8AE" stroke="#173B57" stroke-width="1.8"/>' +
        '<circle cx="40" cy="24" r="6" fill="#39B8AE" stroke="#173B57" stroke-width="1.8"/>' +
        '<circle cx="25" cy="36" r="' + eyeRadius + '" fill="#173B57"/>' +
        '<circle cx="39" cy="36" r="' + eyeRadius + '" fill="#173B57"/>' +
        '<path d="' + mouthPath + '" fill="' + (expression === 'exito' || expression === 'felicitacion' ? '#173B57' : 'none') + '" stroke="#173B57" stroke-width="2.5" stroke-linecap="round"/>' +
      '</svg>'
    );
  }

  /* Generador de polígono de engranaje real con dientes trapezoidales */
  function createGearPolygonPoints(cx, cy, teeth, rOuter, rInner) {
    var pts = [];
    var step = (2 * Math.PI) / teeth;
    for (var i = 0; i < teeth; i++) {
      var a0 = i * step;
      var a1 = a0 + step * 0.15;
      var a2 = a0 + step * 0.28;
      var a3 = a0 + step * 0.58;
      var a4 = a0 + step * 0.71;
      pts.push((cx + rInner * Math.cos(a0)).toFixed(1) + ',' + (cy + rInner * Math.sin(a0)).toFixed(1));
      pts.push((cx + rInner * Math.cos(a1)).toFixed(1) + ',' + (cy + rInner * Math.sin(a1)).toFixed(1));
      pts.push((cx + rOuter * Math.cos(a2)).toFixed(1) + ',' + (cy + rOuter * Math.sin(a2)).toFixed(1));
      pts.push((cx + rOuter * Math.cos(a3)).toFixed(1) + ',' + (cy + rOuter * Math.sin(a3)).toFixed(1));
      pts.push((cx + rInner * Math.cos(a4)).toFixed(1) + ',' + (cy + rInner * Math.sin(a4)).toFixed(1));
    }
    return pts.join(' ');
  }

  /* ==========================================================================
     ESTADO GLOBAL DE PUNTUACIÓN, ESTRELLAS E INSIGNIAS
     ========================================================================== */
  var AppState = {
    data: getDefaultState(),

    load: function () {
      try {
        var raw = window.localStorage.getItem(STORAGE_KEY);
        if (raw) {
          var parsed = JSON.parse(raw);
          if (parsed && typeof parsed === 'object') {
            this.data.stars = parsed.stars || {};
            this.data.badges = parsed.badges || { palancas: false, poleas: false, engranajes: false };
            this.data.diagnosticoDone = !!parsed.diagnosticoDone;
            this.data.finalMissionScore = typeof parsed.finalMissionScore === 'number' ? parsed.finalMissionScore : 0;
            this.data.finalMissionCompleted = !!parsed.finalMissionCompleted;
          }
        }
      } catch (e) {
        this.data = getDefaultState();
      }
      this.renderTopBar();
    },

    save: function () {
      try {
        window.localStorage.setItem(STORAGE_KEY, JSON.stringify(this.data));
      } catch (e) {
        /* Almacenamiento local restringido */
      }
      this.renderTopBar();
    },

    awardStar: function (starId) {
      if (!starId) return false;
      var isNew = !this.data.stars[starId];
      this.data.stars[starId] = true;
      this.save();
      return isNew;
    },

    unlockBadge: function (badgeKey) {
      if (!badgeKey) return;
      this.data.badges[badgeKey] = true;
      this.save();
    },

    getStarCount: function () {
      return Object.keys(this.data.stars || {}).length;
    },

    resetAll: function () {
      this.data = getDefaultState();
      this.save();
    },

    renderTopBar: function () {
      var starCountEls = document.querySelectorAll('#ia-star-count, .js-ia-star-count');
      var countStr = String(this.getStarCount());
      starCountEls.forEach(function (el) {
        el.textContent = countStr;
      });

      var badgePalancas = document.getElementById('ia-chip-palancas');
      if (badgePalancas) badgePalancas.classList.toggle('is-unlocked', !!this.data.badges.palancas);

      var badgePoleas = document.getElementById('ia-chip-poleas');
      if (badgePoleas) badgePoleas.classList.toggle('is-unlocked', !!this.data.badges.poleas);

      var badgeEngranajes = document.getElementById('ia-chip-engranajes');
      if (badgeEngranajes) badgeEngranajes.classList.toggle('is-unlocked', !!this.data.badges.engranajes);
    }
  };

  /* ==========================================================================
     REPRODUCTOR DE AUDIO Y SÍNTESIS DE VOZ ESTRICTA EN ESPAÑOL (PARTE VI)
     ========================================================================== */
  var ControladorAudio = {
    delegatedBound: false,
    spanishVoice: null,
    voicesLoaded: false,

    initVoices: function () {
      var self = this;
      if (!('speechSynthesis' in window)) return;

      function pickSpanishVoice() {
        var voices = window.speechSynthesis.getVoices() || [];
        if (!voices.length) return;
        self.voicesLoaded = true;

        // 1. Priorizar es-CO nativa
        var esCO = voices.find(function (v) { return /^es[-_]CO/i.test(v.lang); });
        // 2. Priorizar español latinoamericano
        var esLatam = voices.find(function (v) { return /^es[-_](MX|419|AR|CL|PE|VE|EC|UY)/i.test(v.lang); });
        // 3. Cualquier otra voz nativa cuyo código de idioma real empiece por 'es'
        var esAny = voices.find(function (v) { return /^es([-_]|$)/i.test(v.lang); });

        self.spanishVoice = esCO || esLatam || esAny || null;
      }

      pickSpanishVoice();
      if (window.speechSynthesis.onvoiceschanged !== undefined) {
        window.speechSynthesis.onvoiceschanged = pickSpanishVoice;
      }
    },

    speakFallbackSpanish: function (text, statusEl) {
      var self = this;
      if (!('speechSynthesis' in window)) {
        if (statusEl) statusEl.textContent = 'Audio no disponible en este visor. Consulta la transcripción textual.';
        return;
      }

      this.initVoices();
      if (!this.spanishVoice) {
        // Prohibido usar una voz inglesa para leer español
        if (statusEl) {
          statusEl.textContent = 'Aviso: No se encontró una voz nativa en español en este sistema. Lee la transcripción desplegable.';
        }
        return;
      }

      window.speechSynthesis.cancel();
      var utter = new SpeechSynthesisUtterance(text);
      utter.voice = this.spanishVoice;
      utter.lang = this.spanishVoice.lang || 'es-CO';
      utter.rate = 0.98;
      utter.onstart = function () {
        if (statusEl) statusEl.textContent = 'Reproduciendo narración en español (' + self.spanishVoice.name + ')...';
      };
      utter.onend = function () {
        if (statusEl) statusEl.textContent = 'Narración finalizada. Pulsa REPETIR si deseas escucharla de nuevo.';
      };
      window.speechSynthesis.speak(utter);
    },

    playBar: function (bar, restart) {
      var self = this;
      if (!bar) return;
      var audio = bar.querySelector('audio');
      var statusEl = bar.querySelector('.ia-audio-status');
      var transcriptEl = bar.querySelector('.ia-transcripcion p');
      var transcriptText = transcriptEl ? transcriptEl.textContent : '';

      // Pausar otros audios activos
      document.querySelectorAll('audio').forEach(function (other) {
        if (other !== audio && !other.paused) {
          other.pause();
        }
      });
      if ('speechSynthesis' in window) {
        window.speechSynthesis.cancel();
      }

      if (!audio) {
        this.speakFallbackSpanish(transcriptText, statusEl);
        return;
      }

      if (restart) {
        try { audio.currentTime = 0; } catch (e) {}
      }

      var fileName = bar.getAttribute('data-audio-file') || (audio.getAttribute('src') || '').split('/').pop();
      var candidates = [
        audio.getAttribute('src'),
        'content/resources/' + fileName,
        '../content/resources/' + fileName,
        'resources/' + fileName,
        fileName
      ].filter(Boolean);

      function tryPlayCandidate(idx) {
        if (idx >= candidates.length) {
          self.speakFallbackSpanish(transcriptText, statusEl);
          return;
        }
        var currentSrc = audio.getAttribute('src');
        if (idx > 0 && candidates[idx] !== currentSrc) {
          audio.setAttribute('src', candidates[idx]);
          audio.load();
        }
        var p = audio.play();
        if (statusEl) statusEl.textContent = restart ? 'Repitiendo narración en español desde el inicio...' : 'Reproduciendo narración en español...';
        if (p && typeof p.catch === 'function') {
          p.catch(function () {
            tryPlayCandidate(idx + 1);
          });
        }
      }

      tryPlayCandidate(0);
    },

    pauseBar: function (bar) {
      if (!bar) return;
      var audio = bar.querySelector('audio');
      var statusEl = bar.querySelector('.ia-audio-status');
      if (audio && !audio.paused) {
        audio.pause();
      }
      if ('speechSynthesis' in window) {
        window.speechSynthesis.pause();
      }
      if (statusEl) statusEl.textContent = 'Audio en pausa. Pulsa REPRODUCIR para continuar.';
    },

    init: function () {
      var self = this;
      this.initVoices();

      if (!this.delegatedBound) {
        this.delegatedBound = true;
        document.addEventListener('click', function (ev) {
          var btn = ev.target && ev.target.closest ? ev.target.closest('[data-audio-action]') : null;
          if (!btn) return;
          var bar = btn.closest('.ia-audio-bar');
          var action = btn.getAttribute('data-audio-action');
          if (action === 'play') {
            self.playBar(bar, false);
          } else if (action === 'pause') {
            self.pauseBar(bar);
          } else if (action === 'restart') {
            self.playBar(bar, true);
          }
        });
      }

      document.querySelectorAll('.ia-audio-bar audio').forEach(function (audio) {
        if (audio.getAttribute('data-ia-bound') === '1') return;
        audio.setAttribute('data-ia-bound', '1');
        audio.addEventListener('ended', function () {
          var bar = audio.closest('.ia-audio-bar');
          var statusEl = bar ? bar.querySelector('.ia-audio-status') : null;
          if (statusEl) {
            statusEl.textContent = 'Narración finalizada. Pulsa REPETIR si deseas escucharla otra vez.';
          }
        });
      });
    }
  };

  /* ==========================================================================
     BOTÓN COMENZAR AVENTURA Y DIAGNÓSTICO DE BIENVENIDA (PÁGINA 1)
     ========================================================================== */
  var ControladorInicio = {
    init: function () {
      var btnComenzar = document.getElementById('btn-comenzar-aventura');
      if (btnComenzar && btnComenzar.getAttribute('data-ia-bound') !== '1') {
        btnComenzar.setAttribute('data-ia-bound', '1');
        btnComenzar.addEventListener('click', function (ev) {
          var diagSection = document.getElementById('seccion-diagnostico-inicial') || document.getElementById('box-inicio-2');
          if (diagSection) {
            ev.preventDefault();
            diagSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
            var firstInput = diagSection.querySelector('button, input, a');
            if (firstInput) firstInput.focus();
          }
        });
      }
    }
  };

  /* ==========================================================================
     JUEGO 1: ¡LEVANTA LA CAJA! (NIVEL 1 - PALANCAS)
     ========================================================================== */
  var JuegoPalancas = {
    container: null,
    currentStep: 0,
    selectedOption: null,
    leoMood: 'descubrimiento',
    coachMsg: 'Maya y yo necesitamos levantar esta caja de 100 kg. ¡Elige una opción y pulsa PROBAR!',
    stepCompleted: [false, false, false],

    challenges: [
      {
        id: 'palanca_reto_1',
        badgeText: 'Reto 1 de 3 · Encuentra el punto de apoyo',
        prompt: '¿Qué posición del punto de apoyo permite levantar la carga con menor esfuerzo si aplicamos la fuerza en el extremo contrario?',
        options: [
          { text: 'Cerca de la carga.', correct: true, fulcrumX: 235 },
          { text: 'En el centro de la barra.', correct: false, fulcrumX: 360 },
          { text: 'Lejos de la carga.', correct: false, fulcrumX: 485 }
        ],
        successMsg: '¡Lo lograste! Al colocar el punto de apoyo cerca de la carga, la barra multiplica tu fuerza y la caja se eleva.',
        errorMsg: '¡Inténtalo de nuevo! Si alejas el punto de apoyo de la carga, necesitarás mucha más fuerza para moverla.'
      },
      {
        id: 'palanca_reto_2',
        badgeText: 'Reto 2 de 3 · Construye la palanca',
        prompt: 'Construye la palanca: elige la posición correcta del punto de apoyo para levantar esta nueva caja pesada:',
        options: [
          { text: 'Posición A: Punto de apoyo junto a la carga.', correct: true, fulcrumX: 235 },
          { text: 'Posición B: Punto de apoyo en el centro.', correct: false, fulcrumX: 360 },
          { text: 'Posición C: Punto de apoyo junto a la fuerza.', correct: false, fulcrumX: 485 }
        ],
        successMsg: '¡Palanca construida con éxito! El punto de apoyo junto a la carga levanta la caja con facilidad.',
        errorMsg: '¡Esa posición no logra levantar la caja! Observa dónde está situada la carga y vuelve a intentarlo.'
      },
      {
        id: 'palanca_reto_3',
        badgeText: 'Reto 3 de 3 · Identifica los elementos',
        prompt: 'Observa la ilustración de la palanca. ¿Cuál de los elementos señalados es el punto de apoyo sobre el que gira la barra?',
        options: [
          { text: 'La caja pesada situada a la izquierda (Carga).', correct: false, fulcrumX: 235 },
          { text: 'El soporte triangular debajo de la barra (El punto de apoyo).', correct: true, fulcrumX: 235 },
          { text: 'El empuje hacia abajo en el extremo derecho (Fuerza).', correct: false, fulcrumX: 235 }
        ],
        successMsg: '¡Excelente identificación! El soporte triangular es el punto de apoyo sobre el que gira toda la barra.',
        errorMsg: '¡Casi! Recuerda que el punto de apoyo es la pieza fija debajo de la barra que le permite girar.'
      }
    ],

    init: function () {
      this.container = document.getElementById('juego-palancas');
      if (!this.container) return;
      this.render();
    },

    getStageSvg: function (fulcrumX) {
      var fx = fulcrumX || 360;
      var p1 = fx + ',175';
      var p2 = (fx - 30) + ',234';
      var p3 = (fx + 30) + ',234';
      return (
        '<svg viewBox="0 0 720 265" width="720" height="265" role="img" aria-label="Escenario interactivo de la palanca con caja pesada a la izquierda, barra rígida y punto de apoyo triangular móvil.">' +
          '<rect width="720" height="265" rx="16" fill="#FFF8E9"/>' +
          '<line x1="40" y1="234" x2="680" y2="234" stroke="#173B57" stroke-width="6" stroke-linecap="round"/>' +
          '<circle cx="235" cy="246" r="5" fill="#39B8AE"/>' +
          '<circle cx="360" cy="246" r="5" fill="#39B8AE"/>' +
          '<circle cx="485" cy="246" r="5" fill="#39B8AE"/>' +
          '<g class="palanca-fulcrum-group">' +
            '<polygon points="' + p1 + ' ' + p2 + ' ' + p3 + '" fill="#39B8AE" stroke="#173B57" stroke-width="4"/>' +
            '<circle cx="' + fx + '" cy="175" r="6" fill="#FFC857" stroke="#173B57" stroke-width="2"/>' +
            '<text x="' + fx + '" y="258" text-anchor="middle" fill="#173B57" font-family="sans-serif" font-size="13" font-weight="bold">PUNTO DE APOYO</text>' +
          '</g>' +
          '<g class="palanca-beam-group">' +
            '<line x1="105" y1="172" x2="615" y2="172" stroke="#173B57" stroke-width="14" stroke-linecap="round"/>' +
            '<g class="palanca-box-group">' +
              '<rect x="112" y="88" width="88" height="78" rx="10" fill="#F28C45" stroke="#173B57" stroke-width="4"/>' +
              '<rect x="126" y="114" width="60" height="26" rx="5" fill="#FFF8E9"/>' +
              '<text x="156" y="132" text-anchor="middle" fill="#173B57" font-family="sans-serif" font-size="14" font-weight="bold">CARGA</text>' +
            '</g>' +
            '<g class="palanca-effort-group">' +
              '<line x1="565" y1="88" x2="565" y2="146" stroke="#FFC857" stroke-width="10" stroke-linecap="round"/>' +
              '<polygon points="565,162 545,136 585,136" fill="#FFC857" stroke="#173B57" stroke-width="3"/>' +
              '<text x="565" y="74" text-anchor="middle" fill="#173B57" font-family="sans-serif" font-size="14" font-weight="bold">FUERZA</text>' +
            '</g>' +
          '</g>' +
        '</svg>'
      );
    },

    render: function () {
      if (!this.container) return;
      var self = this;
      var ch = this.challenges[this.currentStep];
      var currentFulcrumX = this.selectedOption !== null ? ch.options[this.selectedOption].fulcrumX : 360;

      var optionsHtml = ch.options.map(function (opt, idx) {
        var selClass = self.selectedOption === idx ? ' is-selected' : '';
        var pressed = self.selectedOption === idx ? 'true' : 'false';
        return (
          '<button type="button" class="ia-option-btn' + selClass + '" data-opt-index="' + idx + '" aria-pressed="' + pressed + '">' +
            opt.text +
          '</button>'
        );
      }).join('');

      var allDone = this.stepCompleted[0] && this.stepCompleted[1] && this.stepCompleted[2];
      var badgeBanner = allDone ? (
        '<div class="ia-badge-unlocked-banner" role="status">' +
          '<h4>🏅 ¡Insignia obtenida: EXPERTO EN PALANCAS!</h4>' +
          '<p>Has superado los 3 retos de palancas junto a Maya y Leo.</p>' +
        '</div>'
      ) : '';

      this.container.innerHTML =
        '<div class="ia-game-header">' +
          '<h3 class="ia-game-title">🛠️ JUEGO 1: ¡LEVANTA LA CAJA!</h3>' +
          '<span class="ia-game-step-badge">' + ch.badgeText + '</span>' +
        '</div>' +
        '<div class="ia-character-coach">' +
          '<div class="ia-coach-avatar">' + getLeoAvatarSvg(this.leoMood) + '</div>' +
          '<div class="ia-coach-bubble">' +
            '<span class="ia-coach-name">Leo y Maya · Zona de Palancas</span>' +
            '<p class="ia-coach-text">' + this.coachMsg + '</p>' +
          '</div>' +
        '</div>' +
        '<div class="ia-game-prompt">' + ch.prompt + '</div>' +
        '<div class="ia-game-stage" id="palanca-stage">' +
          this.getStageSvg(currentFulcrumX) +
        '</div>' +
        '<div class="ia-options-grid" role="group" aria-label="Opciones del reto de palancas">' +
          optionsHtml +
        '</div>' +
        '<div class="ia-game-actions">' +
          '<button type="button" class="ia-btn ia-btn--primary" id="btn-palanca-probar">PROBAR</button>' +
          '<button type="button" class="ia-btn ia-btn--secondary" id="btn-palanca-reintentar">REINTENTAR</button>' +
          (this.currentStep < this.challenges.length - 1
            ? '<button type="button" class="ia-btn ia-btn--warning" id="btn-palanca-siguiente" ' + (this.stepCompleted[this.currentStep] ? '' : 'disabled') + '>SIGUIENTE RETO</button>'
            : '') +
        '</div>' +
        '<div id="palanca-feedback" aria-live="polite"></div>' +
        badgeBanner;

      this.bindEvents();
    },

    bindEvents: function () {
      var self = this;
      this.container.querySelectorAll('.ia-option-btn').forEach(function (btn) {
        btn.addEventListener('click', function () {
          self.selectedOption = parseInt(btn.getAttribute('data-opt-index'), 10);
          self.leoMood = 'descubrimiento';
          self.coachMsg = 'Opción seleccionada. ¡Ahora pulsa PROBAR para accionar la palanca!';
          self.render();
        });
      });

      var btnProbar = document.getElementById('btn-palanca-probar');
      if (btnProbar) {
        btnProbar.addEventListener('click', function () { self.comprobar(); });
      }

      var btnReintentar = document.getElementById('btn-palanca-reintentar');
      if (btnReintentar) {
        btnReintentar.addEventListener('click', function () { self.reiniciar(); });
      }

      var btnSiguiente = document.getElementById('btn-palanca-siguiente');
      if (btnSiguiente) {
        btnSiguiente.addEventListener('click', function () {
          if (self.currentStep < self.challenges.length - 1) {
            self.currentStep += 1;
            self.selectedOption = null;
            self.leoMood = 'descubrimiento';
            self.coachMsg = '¡Nuevo reto listo! Analiza la posición del punto de apoyo y pulsa PROBAR.';
            self.render();
          }
        });
      }
    },

    comprobar: function () {
      var ch = this.challenges[this.currentStep];
      if (this.selectedOption === null) {
        this.leoMood = 'error';
        this.coachMsg = 'Selecciona primero una de las opciones antes de pulsar PROBAR.';
        this.render();
        var fbEmpty = document.getElementById('palanca-feedback');
        if (fbEmpty) fbEmpty.innerHTML = '<div class="ia-feedback-box is-error">Elige una opción y luego pulsa PROBAR.</div>';
        return;
      }

      var chosen = ch.options[this.selectedOption];
      if (chosen && chosen.correct) {
        this.stepCompleted[this.currentStep] = true;
        AppState.awardStar(ch.id);
        var allDone = this.stepCompleted[0] && this.stepCompleted[1] && this.stepCompleted[2];
        if (allDone) {
          AppState.unlockBadge('palancas');
          this.leoMood = 'felicitacion';
          this.coachMsg = '¡Increíble! Completaste los 3 retos y ganaste la insignia EXPERTO EN PALANCAS.';
        } else {
          this.leoMood = 'exito';
          this.coachMsg = '¡Genial! Observa cómo se inclina la barra y se eleva la caja.';
        }
        this.render();
        var stage = document.getElementById('palanca-stage');
        var fb = document.getElementById('palanca-feedback');
        if (stage) {
          void stage.offsetWidth;
          stage.classList.add('stage-palanca-success');
        }
        if (fb) {
          fb.innerHTML = '<div class="ia-feedback-box is-success">⭐ ' + ch.successMsg + '</div>';
        }
      } else {
        this.leoMood = 'error';
        this.coachMsg = '¡Casi! Prueba acercando el punto de apoyo a la carga y vuelve a pulsar PROBAR.';
        this.render();
        var stageErr = document.getElementById('palanca-stage');
        var fbErr = document.getElementById('palanca-feedback');
        if (stageErr) {
          void stageErr.offsetWidth;
          stageErr.classList.add('stage-palanca-fail');
        }
        if (fbErr) {
          fbErr.innerHTML = '<div class="ia-feedback-box is-error">' + ch.errorMsg + '</div>';
        }
      }
    },

    reiniciar: function () {
      this.selectedOption = null;
      this.leoMood = 'descubrimiento';
      this.coachMsg = 'Escenario reiniciado. Selecciona una opción y pulsa PROBAR.';
      this.render();
    }
  };

  /* ==========================================================================
     JUEGO 2: ¡RESCATE DE CAJAS! (NIVEL 2 - POLEAS)
     ========================================================================== */
  var JuegoPoleas = {
    container: null,
    currentStep: 0,
    selectedOption: null,
    leoMood: 'descubrimiento',
    coachMsg: 'Bruno necesita subir las cajas a la plataforma alta. ¡Elige la polea adecuada!',
    stepCompleted: [false, false, false],

    challenges: [
      {
        id: 'polea_mision_1',
        badgeText: 'Reto 1 de 3 · Elige la polea correcta',
        prompt: '¿Qué tipo de polea permite tirar de la cuerda hacia abajo para subir una carga?',
        animMode: 'fixed',
        options: [
          { text: 'Polea fija.', correct: true },
          { text: 'Polea móvil.', correct: false }
        ],
        successMsg: '¡Rescate conseguido! La polea fija cambia la dirección de la fuerza: tiras hacia abajo y la caja sube.',
        errorMsg: '¡Inténtalo de nuevo! Recuerda que la polea fija está sujeta arriba y cambia la dirección del tirón.'
      },
      {
        id: 'polea_mision_2',
        badgeText: 'Reto 2 de 3 · Reduce el esfuerzo',
        prompt: '¿Qué tipo de polea ayuda a levantar una carga aplicando menos fuerza?',
        animMode: 'movable',
        options: [
          { text: 'Polea fija.', correct: false },
          { text: 'Polea móvil.', correct: true }
        ],
        successMsg: '¡Muy bien! La polea móvil se mueve junto con la carga y reduce la fuerza necesaria.',
        errorMsg: '¡Inténtalo de nuevo! Busca la polea que sube junto con la carga para repartir el peso.'
      },
      {
        id: 'polea_mision_3',
        badgeText: 'Reto 3 de 3 · Reconoce el mecanismo',
        prompt: 'Observa las dos ilustraciones y selecciona cuál representa la polea móvil (la que se mueve junto con la carga):',
        animMode: 'movable',
        isImageChoice: true,
        options: [
          {
            text: 'Mecanismo A',
            imgFile: 'ilustracion_polea_fija_card.svg',
            alt: 'Rueda sujeta a un soporte fijo en la parte superior',
            correct: false
          },
          {
            text: 'Mecanismo B',
            imgFile: 'ilustracion_polea_movil_card.svg',
            alt: 'Rueda conectada directamente a la carga que se eleva con ella',
            correct: true
          }
        ],
        successMsg: '¡Excelente rescate! Has identificado correctamente la polea móvil unida a la carga.',
        errorMsg: '¡Observa con atención! En el Mecanismo A la rueda está fija al techo; busca aquella cuya rueda está unida a la caja.'
      }
    ],

    init: function () {
      this.container = document.getElementById('juego-poleas');
      if (!this.container) return;
      this.render();
    },

    getResPrefix: function () {
      return this.container && this.container.getAttribute('data-res-prefix')
        ? this.container.getAttribute('data-res-prefix')
        : '../content/resources/';
    },

    getStageSvg: function (mode) {
      if (mode === 'movable') {
        return (
          '<svg viewBox="0 0 720 275" width="720" height="275" role="img" aria-label="Escenario de rescate con plataforma alta y sistema de polea móvil unida a la caja.">' +
            '<rect width="720" height="275" rx="16" fill="#FFF8E9"/>' +
            '<rect x="45" y="95" width="165" height="16" rx="5" fill="#173B57"/>' +
            '<rect x="60" y="111" width="18" height="135" fill="#173B57"/>' +
            '<text x="125" y="84" text-anchor="middle" fill="#173B57" font-family="sans-serif" font-size="14" font-weight="bold">PLATAFORMA ALTA</text>' +
            '<rect x="230" y="24" width="380" height="16" rx="6" fill="#173B57"/>' +
            '<line x1="40" y1="246" x2="680" y2="246" stroke="#173B57" stroke-width="6"/>' +
            '<line x1="365" y1="40" x2="365" y2="175" stroke="#F28C45" stroke-width="5"/>' +
            '<line x1="435" y1="40" x2="435" y2="175" stroke="#39B8AE" stroke-width="5" stroke-dasharray="9,5"/>' +
            '<g class="polea-movable-assembly">' +
              '<g class="polea-wheel-spin">' +
                '<circle cx="400" cy="155" r="32" fill="#39B8AE" stroke="#173B57" stroke-width="5"/>' +
                '<line x1="375" y1="155" x2="425" y2="155" stroke="#173B57" stroke-width="3"/>' +
                '<line x1="400" y1="130" x2="400" y2="180" stroke="#173B57" stroke-width="3"/>' +
                '<circle cx="400" cy="155" r="9" fill="#FFF8E9" stroke="#173B57" stroke-width="3"/>' +
              '</g>' +
              '<line x1="400" y1="187" x2="400" y2="202" stroke="#173B57" stroke-width="5"/>' +
              '<rect x="355" y="198" width="90" height="46" rx="8" fill="#F28C45" stroke="#173B57" stroke-width="3.5"/>' +
              '<text x="400" y="226" text-anchor="middle" fill="#173B57" font-family="sans-serif" font-size="14" font-weight="bold">CARGA</text>' +
            '</g>' +
            '<g class="polea-rope-pull">' +
              '<polygon points="435,98 422,122 448,122" fill="#39B8AE" stroke="#173B57" stroke-width="2.5"/>' +
              '<text x="540" y="115" fill="#173B57" font-family="sans-serif" font-size="14" font-weight="bold">MENOS FUERZA</text>' +
            '</g>' +
          '</svg>'
        );
      }

      return (
        '<svg viewBox="0 0 720 275" width="720" height="275" role="img" aria-label="Escenario de rescate con polea fija sujeta al soporte superior para subir la carga tirando hacia abajo.">' +
          '<rect width="720" height="275" rx="16" fill="#FFF8E9"/>' +
          '<rect x="45" y="95" width="165" height="16" rx="5" fill="#173B57"/>' +
          '<rect x="60" y="111" width="18" height="135" fill="#173B57"/>' +
          '<text x="125" y="84" text-anchor="middle" fill="#173B57" font-family="sans-serif" font-size="14" font-weight="bold">PLATAFORMA ALTA</text>' +
          '<rect x="230" y="24" width="380" height="16" rx="6" fill="#173B57"/>' +
          '<line x1="400" y1="40" x2="400" y2="75" stroke="#173B57" stroke-width="7"/>' +
          '<line x1="40" y1="246" x2="680" y2="246" stroke="#173B57" stroke-width="6"/>' +
          '<line x1="366" y1="75" x2="366" y2="205" stroke="#F28C45" stroke-width="5"/>' +
          '<line x1="434" y1="75" x2="434" y2="205" stroke="#39B8AE" stroke-width="5" stroke-dasharray="9,5"/>' +
          '<g class="polea-wheel-spin">' +
            '<circle cx="400" cy="75" r="34" fill="#FFC857" stroke="#173B57" stroke-width="5"/>' +
            '<line x1="374" y1="75" x2="426" y2="75" stroke="#173B57" stroke-width="3"/>' +
            '<line x1="400" y1="49" x2="400" y2="101" stroke="#173B57" stroke-width="3"/>' +
            '<circle cx="400" cy="75" r="10" fill="#173B57"/>' +
          '</g>' +
          '<g class="polea-load-group">' +
            '<rect x="321" y="196" width="90" height="48" rx="8" fill="#F28C45" stroke="#173B57" stroke-width="3.5"/>' +
            '<text x="366" y="225" text-anchor="middle" fill="#173B57" font-family="sans-serif" font-size="14" font-weight="bold">CARGA</text>' +
          '</g>' +
          '<g class="polea-rope-pull">' +
            '<polygon points="434,158 421,134 447,134" fill="#39B8AE" stroke="#173B57" stroke-width="2.5"/>' +
            '<text x="535" y="150" fill="#173B57" font-family="sans-serif" font-size="14" font-weight="bold">TIRAR HACIA ABAJO</text>' +
          '</g>' +
        '</svg>'
      );
    },

    render: function () {
      if (!this.container) return;
      var self = this;
      var ch = this.challenges[this.currentStep];
      var resPrefix = this.getResPrefix();

      var optionsHtml = ch.options.map(function (opt, idx) {
        var selClass = self.selectedOption === idx ? ' is-selected' : '';
        var pressed = self.selectedOption === idx ? 'true' : 'false';
        var inner = opt.imgFile
          ? '<img src="' + resPrefix + opt.imgFile + '" alt="' + opt.alt + '"/><span>' + opt.text + '</span>'
          : opt.text;
        return (
          '<button type="button" class="ia-option-btn' + selClass + '" data-opt-index="' + idx + '" aria-pressed="' + pressed + '">' +
            inner +
          '</button>'
        );
      }).join('');

      var allDone = this.stepCompleted[0] && this.stepCompleted[1] && this.stepCompleted[2];
      var badgeBanner = allDone ? (
        '<div class="ia-badge-unlocked-banner" role="status">' +
          '<h4>🏅 ¡Insignia obtenida: EXPERTO EN POLEAS!</h4>' +
          '<p>Has completado los 3 retos de elevación junto a Bruno y Leo.</p>' +
        '</div>'
      ) : '';

      this.container.innerHTML =
        '<div class="ia-game-header">' +
          '<h3 class="ia-game-title">🏗️ JUEGO 2: ¡RESCATE DE CAJAS!</h3>' +
          '<span class="ia-game-step-badge">' + ch.badgeText + '</span>' +
        '</div>' +
        '<div class="ia-character-coach">' +
          '<div class="ia-coach-avatar">' + getLeoAvatarSvg(this.leoMood) + '</div>' +
          '<div class="ia-coach-bubble">' +
            '<span class="ia-coach-name">Leo y Bruno · Zona de Poleas</span>' +
            '<p class="ia-coach-text">' + this.coachMsg + '</p>' +
          '</div>' +
        '</div>' +
        '<div class="ia-game-prompt">' + ch.prompt + '</div>' +
        '<div class="ia-game-stage" id="polea-stage">' +
          this.getStageSvg(ch.animMode) +
        '</div>' +
        '<div class="ia-options-grid" role="group" aria-label="Opciones del reto de poleas">' +
          optionsHtml +
        '</div>' +
        '<div class="ia-game-actions">' +
          '<button type="button" class="ia-btn ia-btn--primary" id="btn-polea-probar">COMPROBAR</button>' +
          '<button type="button" class="ia-btn ia-btn--secondary" id="btn-polea-reintentar">REINTENTAR</button>' +
          (this.currentStep < this.challenges.length - 1
            ? '<button type="button" class="ia-btn ia-btn--warning" id="btn-polea-siguiente" ' + (this.stepCompleted[this.currentStep] ? '' : 'disabled') + '>SIGUIENTE RETO</button>'
            : '') +
        '</div>' +
        '<div id="polea-feedback" aria-live="polite"></div>' +
        badgeBanner;

      this.bindEvents();
    },

    bindEvents: function () {
      var self = this;
      this.container.querySelectorAll('.ia-option-btn').forEach(function (btn) {
        btn.addEventListener('click', function () {
          self.selectedOption = parseInt(btn.getAttribute('data-opt-index'), 10);
          self.leoMood = 'descubrimiento';
          self.coachMsg = 'Opción elegida. ¡Pulsa COMPROBAR para poner en marcha la cuerda y la polea!';
          self.render();
        });
      });

      var btnProbar = document.getElementById('btn-polea-probar');
      if (btnProbar) {
        btnProbar.addEventListener('click', function () { self.comprobar(); });
      }

      var btnReintentar = document.getElementById('btn-polea-reintentar');
      if (btnReintentar) {
        btnReintentar.addEventListener('click', function () { self.reiniciar(); });
      }

      var btnSiguiente = document.getElementById('btn-polea-siguiente');
      if (btnSiguiente) {
        btnSiguiente.addEventListener('click', function () {
          if (self.currentStep < self.challenges.length - 1) {
            self.currentStep += 1;
            self.selectedOption = null;
            self.leoMood = 'descubrimiento';
            self.coachMsg = '¡Siguiente reto de rescate! Elige la polea correcta y pulsa COMPROBAR.';
            self.render();
          }
        });
      }
    },

    comprobar: function () {
      var ch = this.challenges[this.currentStep];
      if (this.selectedOption === null) {
        this.leoMood = 'error';
        this.coachMsg = 'Primero selecciona una opción y luego pulsa COMPROBAR.';
        this.render();
        var fbEmpty = document.getElementById('polea-feedback');
        if (fbEmpty) fbEmpty.innerHTML = '<div class="ia-feedback-box is-error">Selecciona una opción antes de comprobar.</div>';
        return;
      }

      var chosen = ch.options[this.selectedOption];
      if (chosen && chosen.correct) {
        this.stepCompleted[this.currentStep] = true;
        AppState.awardStar(ch.id);
        var allDone = this.stepCompleted[0] && this.stepCompleted[1] && this.stepCompleted[2];
        if (allDone) {
          AppState.unlockBadge('poleas');
          this.leoMood = 'felicitacion';
          this.coachMsg = '¡Rescate completado! Ganaste la insignia EXPERTO EN POLEAS.';
        } else {
          this.leoMood = 'exito';
          this.coachMsg = '¡Mira cómo giran las poleas y sube la carga!';
        }
        this.render();
        var stage = document.getElementById('polea-stage');
        var fb = document.getElementById('polea-feedback');
        if (stage) {
          void stage.offsetWidth;
          stage.classList.add('stage-polea-active');
          stage.classList.add(ch.animMode === 'fixed' ? 'stage-polea-fixed-success' : 'stage-polea-movable-success');
        }
        if (fb) {
          fb.innerHTML = '<div class="ia-feedback-box is-success">⭐ ' + ch.successMsg + '</div>';
        }
      } else {
        this.leoMood = 'error';
        this.coachMsg = '¡Inténtalo otra vez! Fíjate si la polea está fija al techo o se mueve con la carga.';
        this.render();
        var stageErr = document.getElementById('polea-stage');
        var fbErr = document.getElementById('polea-feedback');
        if (stageErr) {
          void stageErr.offsetWidth;
          stageErr.classList.add('stage-polea-fail');
        }
        if (fbErr) {
          fbErr.innerHTML = '<div class="ia-feedback-box is-error">' + ch.errorMsg + '</div>';
        }
      }
    },

    reiniciar: function () {
      this.selectedOption = null;
      this.leoMood = 'descubrimiento';
      this.coachMsg = 'Poleas listas. Selecciona tu respuesta y pulsa COMPROBAR.';
      this.render();
    }
  };

  /* ==========================================================================
     JUEGO 3: ¡ACTIVA LA FÁBRICA! (NIVEL 3 - ENGRANAJES CON DIENTES REALES)
     ========================================================================== */
  var JuegoEngranajes = {
    container: null,
    currentStep: 0,
    selectedOption: null,
    isSpinning: false,
    leoMood: 'descubrimiento',
    coachMsg: 'Nora necesita activar los engranajes de la fábrica. ¡Elige una opción y pulsa ENCENDER FÁBRICA!',
    stepCompleted: [false, false, false],

    challenges: [
      {
        id: 'engranaje_reto_1',
        badgeText: 'Reto 1 de 3 · Descubre el sentido de giro',
        prompt: 'Si el primer engranaje gira hacia la derecha, ¿hacia dónde gira el segundo engranaje que está en contacto directo?',
        sceneType: 'two_contact',
        options: [
          { text: 'Hacia la derecha.', correct: false },
          { text: 'Hacia la izquierda.', correct: true }
        ],
        successMsg: '¡Correcto! Dos engranajes en contacto directo giran siempre en sentidos opuestos.',
        errorMsg: '¡Observa los dientes! Cuando el primero empuja hacia abajo en el centro, hace girar al segundo en sentido contrario.'
      },
      {
        id: 'engranaje_reto_2',
        badgeText: 'Reto 2 de 3 · Conecta los engranajes',
        prompt: 'Selecciona la configuración que permite conectar correctamente las ruedas dentadas para activar la máquina:',
        sceneType: 'connect_slot',
        options: [
          { text: 'Configuración 1: Engranaje central engranado tocando ambos dientes.', correct: true },
          { text: 'Configuración 2: Engranaje central separado arriba sin contacto.', correct: false }
        ],
        successMsg: '¡La fábrica está funcionando! Los tres engranajes transmiten el movimiento hasta la máquina.',
        errorMsg: '¡Los dientes no se tocan! Elige la configuración que encaja las ruedas dentadas entre sí.'
      },
      {
        id: 'engranaje_reto_3',
        badgeText: 'Reto 3 de 3 · Controla la velocidad',
        prompt: 'Si un engranaje pequeño mueve uno grande, ¿cómo gira el engranaje grande?',
        sceneType: 'small_to_large',
        options: [
          { text: 'Más lentamente.', correct: true },
          { text: 'Más rápidamente.', correct: false },
          { text: 'A la misma velocidad.', correct: false }
        ],
        successMsg: '¡Excelente! Como el engranaje grande tiene más dientes, tarda más en completar una vuelta y gira más lentamente.',
        errorMsg: '¡Fíjate en el tamaño! El engranaje grande tiene muchos más dientes por recorrer que el pequeño.'
      }
    ],

    init: function () {
      this.container = document.getElementById('juego-engranajes');
      if (!this.container) return;
      this.render();
    },

    renderToothedGearGroup: function (cx, cy, teeth, rOuter, rInner, fill, animClass, label) {
      var polyPoints = createGearPolygonPoints(cx, cy, teeth, rOuter, rInner);
      return (
        '<g class="gear-rotatable ' + (animClass || '') + '">' +
          '<polygon points="' + polyPoints + '" fill="' + fill + '" stroke="#173B57" stroke-width="3.5"/>' +
          '<line x1="' + (cx - rInner + 8) + '" y1="' + cy + '" x2="' + (cx + rInner - 8) + '" y2="' + cy + '" stroke="#173B57" stroke-width="3.5"/>' +
          '<line x1="' + cx + '" y1="' + (cy - rInner + 8) + '" x2="' + cx + '" y2="' + (cy + rInner - 8) + '" stroke="#173B57" stroke-width="3.5"/>' +
          '<circle cx="' + cx + '" cy="' + cy + '" r="' + Math.round(rInner * 0.32) + '" fill="#FFF8E9" stroke="#173B57" stroke-width="3.5"/>' +
        '</g>' +
        (label ? '<text x="' + cx + '" y="' + (cy + rOuter + 24) + '" text-anchor="middle" fill="#173B57" font-family="sans-serif" font-size="14" font-weight="bold">' + label + '</text>' : '')
      );
    },

    getStageSvg: function (ch) {
      var spin = this.isSpinning;
      if (ch.sceneType === 'two_contact') {
        var g1Anim = spin ? 'gear-spin-cw' : '';
        var g2Anim = spin ? 'gear-spin-ccw' : '';
        return (
          '<svg viewBox="0 0 720 265" width="720" height="265" role="img" aria-label="Dos engranajes con dientes visibles en contacto directo.">' +
            '<rect width="720" height="265" rx="16" fill="#FFF8E9"/>' +
            '<rect x="95" y="20" width="530" height="225" rx="18" fill="#FFFFFF" stroke="#173B57" stroke-width="3.5"/>' +
            this.renderToothedGearGroup(292, 122, 12, 66, 52, '#39B8AE', g1Anim, '1. MOTOR (Derecha ↻)') +
            this.renderToothedGearGroup(418, 122, 12, 66, 52, '#F28C45', g2Anim, '2. ENGRANAJE EN CONTACTO') +
          '</svg>'
        );
      }

      if (ch.sceneType === 'connect_slot') {
        var middleConnected = this.selectedOption !== 1;
        var midY = middleConnected ? 122 : 52;
        var motorAnim = spin ? 'gear-spin-cw' : '';
        var midAnim = (spin && middleConnected) ? 'gear-spin-ccw' : '';
        var outAnim = (spin && middleConnected) ? 'gear-spin-cw' : '';
        var machineLight = (spin && middleConnected) ? '#39B8AE' : '#D5E2EC';
        var machineText = (spin && middleConnected) ? '¡FÁBRICA ACTIVA!' : 'EN ESPERA';

        return (
          '<svg viewBox="0 0 720 265" width="720" height="265" role="img" aria-label="Sistema de tres engranajes con dientes conectando el motor y la máquina de la fábrica.">' +
            '<rect width="720" height="265" rx="16" fill="#FFF8E9"/>' +
            '<rect x="40" y="20" width="640" height="225" rx="18" fill="#FFFFFF" stroke="#173B57" stroke-width="3.5"/>' +
            '<circle cx="305" cy="122" r="50" fill="none" stroke="#39B8AE" stroke-width="2.5" stroke-dasharray="7,5"/>' +
            this.renderToothedGearGroup(192, 122, 11, 58, 45, '#39B8AE', motorAnim, '1. MOTOR') +
            this.renderToothedGearGroup(305, midY, 10, 54, 42, '#FFC857', midAnim, middleConnected ? '2. CONECTADO' : '2. SEPARADO') +
            this.renderToothedGearGroup(418, 122, 11, 58, 45, '#F28C45', outAnim, '3. SALIDA') +
            '<rect x="515" y="68" width="135" height="108" rx="14" fill="#173B57"/>' +
            '<circle cx="582" cy="108" r="20" fill="' + machineLight + '" stroke="#FFF8E9" stroke-width="3"/>' +
            '<text x="582" y="154" text-anchor="middle" fill="#FFC857" font-family="sans-serif" font-size="12" font-weight="bold">' + machineText + '</text>' +
          '</svg>'
        );
      }

      var smallAnim = spin ? 'gear-spin-cw-fast' : '';
      var largeAnim = spin ? 'gear-spin-ccw-slow' : '';
      return (
        '<svg viewBox="0 0 720 265" width="720" height="265" role="img" aria-label="Engranaje pequeño moviendo un engranaje grande con dientes visibles.">' +
          '<rect width="720" height="265" rx="16" fill="#FFF8E9"/>' +
          '<rect x="95" y="18" width="530" height="228" rx="18" fill="#FFFFFF" stroke="#173B57" stroke-width="3.5"/>' +
          this.renderToothedGearGroup(272, 122, 8, 44, 33, '#FFC857', smallAnim, 'PEQUEÑO (Rápido ↻)') +
          this.renderToothedGearGroup(396, 122, 16, 82, 68, '#39B8AE', largeAnim, 'GRANDE (Más lento ↺)') +
        '</svg>'
      );
    },

    render: function () {
      if (!this.container) return;
      var self = this;
      var ch = this.challenges[this.currentStep];

      var optionsHtml = ch.options.map(function (opt, idx) {
        var selClass = self.selectedOption === idx ? ' is-selected' : '';
        var pressed = self.selectedOption === idx ? 'true' : 'false';
        return (
          '<button type="button" class="ia-option-btn' + selClass + '" data-opt-index="' + idx + '" aria-pressed="' + pressed + '">' +
            opt.text +
          '</button>'
        );
      }).join('');

      var allDone = this.stepCompleted[0] && this.stepCompleted[1] && this.stepCompleted[2];
      var badgeBanner = allDone ? (
        '<div class="ia-badge-unlocked-banner" role="status">' +
          '<h4>🏅 ¡Insignia obtenida: EXPERTO EN ENGRANAJES!</h4>' +
          '<p>Has puesto en marcha toda la fábrica junto a Nora y Leo.</p>' +
        '</div>'
      ) : '';

      this.container.innerHTML =
        '<div class="ia-game-header">' +
          '<h3 class="ia-game-title">⚙️ JUEGO 3: ¡ACTIVA LA FÁBRICA!</h3>' +
          '<span class="ia-game-step-badge">' + ch.badgeText + '</span>' +
        '</div>' +
        '<div class="ia-character-coach">' +
          '<div class="ia-coach-avatar">' + getLeoAvatarSvg(this.leoMood) + '</div>' +
          '<div class="ia-coach-bubble">' +
            '<span class="ia-coach-name">Leo y Nora · Fábrica de Engranajes</span>' +
            '<p class="ia-coach-text">' + this.coachMsg + '</p>' +
          '</div>' +
        '</div>' +
        '<div class="ia-game-prompt">' + ch.prompt + '</div>' +
        '<div class="ia-game-stage" id="engranaje-stage">' +
          this.getStageSvg(ch) +
        '</div>' +
        '<div class="ia-options-grid" role="group" aria-label="Opciones del reto de engranajes">' +
          optionsHtml +
        '</div>' +
        '<div class="ia-game-actions">' +
          '<button type="button" class="ia-btn ia-btn--primary" id="btn-engranaje-probar">ENCENDER FÁBRICA</button>' +
          '<button type="button" class="ia-btn ia-btn--secondary" id="btn-engranaje-reintentar">REINTENTAR</button>' +
          (this.currentStep < this.challenges.length - 1
            ? '<button type="button" class="ia-btn ia-btn--warning" id="btn-engranaje-siguiente" ' + (this.stepCompleted[this.currentStep] ? '' : 'disabled') + '>SIGUIENTE RETO</button>'
            : '') +
        '</div>' +
        '<div id="engranaje-feedback" aria-live="polite"></div>' +
        badgeBanner;

      this.bindEvents();
    },

    bindEvents: function () {
      var self = this;
      this.container.querySelectorAll('.ia-option-btn').forEach(function (btn) {
        btn.addEventListener('click', function () {
          self.selectedOption = parseInt(btn.getAttribute('data-opt-index'), 10);
          self.isSpinning = false;
          self.leoMood = 'descubrimiento';
          self.coachMsg = 'Configuración seleccionada. ¡Pulsa ENCENDER FÁBRICA para probar el giro!';
          self.render();
        });
      });

      var btnProbar = document.getElementById('btn-engranaje-probar');
      if (btnProbar) {
        btnProbar.addEventListener('click', function () { self.comprobar(); });
      }

      var btnReintentar = document.getElementById('btn-engranaje-reintentar');
      if (btnReintentar) {
        btnReintentar.addEventListener('click', function () { self.reiniciar(); });
      }

      var btnSiguiente = document.getElementById('btn-engranaje-siguiente');
      if (btnSiguiente) {
        btnSiguiente.addEventListener('click', function () {
          if (self.currentStep < self.challenges.length - 1) {
            self.currentStep += 1;
            self.selectedOption = null;
            self.isSpinning = false;
            self.leoMood = 'descubrimiento';
            self.coachMsg = '¡Siguiente reto de engranajes! Observa el tamaño y la conexión de las ruedas.';
            self.render();
          }
        });
      }
    },

    comprobar: function () {
      var ch = this.challenges[this.currentStep];
      if (this.selectedOption === null) {
        this.leoMood = 'error';
        this.coachMsg = 'Elige primero una opción antes de pulsar ENCENDER FÁBRICA.';
        this.render();
        var fbEmpty = document.getElementById('engranaje-feedback');
        if (fbEmpty) fbEmpty.innerHTML = '<div class="ia-feedback-box is-error">Selecciona una opción antes de encender la fábrica.</div>';
        return;
      }

      var chosen = ch.options[this.selectedOption];
      if (chosen && chosen.correct) {
        this.isSpinning = true;
        this.stepCompleted[this.currentStep] = true;
        AppState.awardStar(ch.id);
        var allDone = this.stepCompleted[0] && this.stepCompleted[1] && this.stepCompleted[2];
        if (allDone) {
          AppState.unlockBadge('engranajes');
          this.leoMood = 'felicitacion';
          this.coachMsg = '¡Fábrica en marcha al 100%! Desbloqueaste la insignia EXPERTO EN ENGRANAJES.';
        } else {
          this.leoMood = 'exito';
          this.coachMsg = '¡Mira cómo encajan los dientes y giran las ruedas!';
        }
        this.render();
        var fbAfter = document.getElementById('engranaje-feedback');
        if (fbAfter) {
          fbAfter.innerHTML = '<div class="ia-feedback-box is-success">⭐ ' + ch.successMsg + '</div>';
        }
      } else {
        this.isSpinning = false;
        this.leoMood = 'error';
        this.coachMsg = '¡Revisa el contacto y los dientes de las ruedas e inténtalo de nuevo!';
        this.render();
        var fbErr = document.getElementById('engranaje-feedback');
        if (fbErr) {
          fbErr.innerHTML = '<div class="ia-feedback-box is-error">' + ch.errorMsg + '</div>';
        }
      }
    },

    reiniciar: function () {
      this.selectedOption = null;
      this.isSpinning = false;
      this.leoMood = 'descubrimiento';
      this.coachMsg = 'Engranajes detenidos. Elige una opción y pulsa ENCENDER FÁBRICA.';
      this.render();
    }
  };

  /* ==========================================================================
     PÁGINA 5: MISIÓN FINAL (TRES RETOS UNO A UNO, AVANZA SOLO AL ACERTAR)
     ========================================================================== */
  var GranMisionFinal = {
    container: null,
    currentStep: 0,
    selectedOption: null,
    currentStepSolved: false,
    leoMood: 'descubrimiento',
    coachMsg: 'Observa la ilustración de este desafío y elige la máquina simple correcta.',
    finishedAll: false,

    challenges: [
      {
        id: 'mision_final_1',
        badgeText: 'Reto Final 1 de 3',
        imgFile: 'ilustracion_mision_reto1.svg',
        imgAlt: 'Imagen de una piedra pesada que debe levantarse con una barra y un punto de apoyo.',
        prompt: '¿Qué máquina simple utilizarías?',
        options: [
          { text: 'Palanca.', correct: true },
          { text: 'Polea.', correct: false },
          { text: 'Engranajes.', correct: false }
        ],
        successMsg: '¡Correcto! La palanca apoyada en un punto de apoyo permite levantar la piedra pesada.',
        errorMsg: 'Observa la barra rígida apoyada sobre la piedra pequeña. ¡Inténtalo de nuevo!'
      },
      {
        id: 'mision_final_2',
        badgeText: 'Reto Final 2 de 3',
        imgFile: 'ilustracion_mision_reto2.svg',
        imgAlt: 'Imagen de una carga suspendida de una cuerda y una rueda.',
        prompt: '¿Qué mecanismo permite levantar la carga?',
        options: [
          { text: 'Engranajes.', correct: false },
          { text: 'Polea.', correct: true },
          { text: 'Palanca.', correct: false }
        ],
        successMsg: '¡Correcto! La polea utiliza una rueda acanalada y una cuerda para izar la carga.',
        errorMsg: 'Fíjate en la cuerda que pasa por la rueda superior. ¡Vuelve a intentarlo!'
      },
      {
        id: 'mision_final_3',
        badgeText: 'Reto Final 3 de 3',
        imgFile: 'ilustracion_mision_reto3.svg',
        imgAlt: 'Imagen de dos ruedas dentadas en contacto.',
        prompt: '¿Qué mecanismo transmite el movimiento?',
        options: [
          { text: 'Polea.', correct: false },
          { text: 'Palanca.', correct: false },
          { text: 'Engranajes.', correct: true }
        ],
        successMsg: '¡Correcto! Los engranajes son ruedas dentadas que transmiten el movimiento entre sí.',
        errorMsg: 'Observa los dientes de las dos ruedas conectadas. ¡Elige otra opción y pulsa COMPROBAR!'
      }
    ],

    init: function () {
      this.container = document.getElementById('juego-mision-final');
      if (!this.container) return;
      this.render();
    },

    getResPrefix: function () {
      return this.container && this.container.getAttribute('data-res-prefix')
        ? this.container.getAttribute('data-res-prefix')
        : '../content/resources/';
    },

    render: function () {
      if (!this.container) return;
      var self = this;
      var resPrefix = this.getResPrefix();

      if (this.finishedAll) {
        AppState.data.finalMissionScore = 3;
        AppState.data.finalMissionCompleted = true;
        AppState.save();

        this.container.innerHTML =
          '<div class="ia-game-header">' +
            '<h3 class="ia-game-title">🏆 ¡MISIÓN FINAL SUPERADA!</h3>' +
            '<span class="ia-game-step-badge">3 de 3 Estrellas de Misión</span>' +
          '</div>' +
          '<div class="ia-character-coach">' +
            '<div class="ia-coach-avatar">' + getLeoAvatarSvg('felicitacion') + '</div>' +
            '<div class="ia-coach-bubble">' +
              '<span class="ia-coach-name">Leo, Maya, Bruno y Nora</span>' +
              '<p class="ia-coach-text">¡Increíble! Has resuelto los 3 retos del taller y demostrado que eres un inventor experto.</p>' +
            '</div>' +
          '</div>' +
          '<div class="ia-feedback-box is-success" style="margin-bottom:20px;">' +
            '⭐⭐⭐ ¡Has obtenido las 3 estrellas de la Misión Final!' +
          '</div>' +
          '<div class="ia-game-actions">' +
            '<button type="button" class="ia-btn ia-btn--secondary" id="btn-mision-repetir-todo">REINTENTAR MISIÓN</button>' +
            '<a href="final-inventor-experto.html" class="ia-btn ia-btn--primary">VER MIS RECOMPENSAS</a>' +
            '<a href="../index.html" class="ia-btn ia-btn--warning">VOLVER AL INICIO</a>' +
          '</div>';

        var btnRepeatAll = document.getElementById('btn-mision-repetir-todo');
        if (btnRepeatAll) {
          btnRepeatAll.addEventListener('click', function () {
            self.currentStep = 0;
            self.selectedOption = null;
            self.currentStepSolved = false;
            self.finishedAll = false;
            self.leoMood = 'descubrimiento';
            self.coachMsg = 'Observa la ilustración de este desafío y elige la máquina simple correcta.';
            self.render();
          });
        }
        return;
      }

      var ch = this.challenges[this.currentStep];
      var optionsHtml = ch.options.map(function (opt, idx) {
        var selClass = self.selectedOption === idx ? ' is-selected' : '';
        var pressed = self.selectedOption === idx ? 'true' : 'false';
        return (
          '<button type="button" class="ia-option-btn' + selClass + '" data-opt-index="' + idx + '" aria-pressed="' + pressed + '">' +
            opt.text +
          '</button>'
        );
      }).join('');

      var nextLabel = this.currentStep < this.challenges.length - 1 ? 'SIGUIENTE RETO' : 'COMPLETAR MISIÓN';

      this.container.innerHTML =
        '<div class="ia-game-header">' +
          '<h3 class="ia-game-title">🚨 MISIÓN FINAL: ¡DEMUESTRA QUE ERES UN INVENTOR EXPERTO!</h3>' +
          '<span class="ia-game-step-badge">' + ch.badgeText + '</span>' +
        '</div>' +
        '<div class="ia-character-coach">' +
          '<div class="ia-coach-avatar">' + getLeoAvatarSvg(this.leoMood) + '</div>' +
          '<div class="ia-coach-bubble">' +
            '<span class="ia-coach-name">Leo · Misión Final del Taller</span>' +
            '<p class="ia-coach-text">' + this.coachMsg + '</p>' +
          '</div>' +
        '</div>' +
        '<div class="ia-illustration-box">' +
          '<img src="' + resPrefix + ch.imgFile + '" alt="' + ch.imgAlt + '" width="780" height="300"/>' +
        '</div>' +
        '<div class="ia-game-prompt">' + ch.prompt + '</div>' +
        '<div class="ia-options-grid" role="group" aria-label="Opciones del reto final">' +
          optionsHtml +
        '</div>' +
        '<div class="ia-game-actions">' +
          '<button type="button" class="ia-btn ia-btn--primary" id="btn-mision-comprobar">COMPROBAR</button>' +
          '<button type="button" class="ia-btn ia-btn--secondary" id="btn-mision-reintentar">REINTENTAR</button>' +
          '<button type="button" class="ia-btn ia-btn--warning" id="btn-mision-siguiente" ' + (this.currentStepSolved ? '' : 'disabled') + '>' + nextLabel + '</button>' +
        '</div>' +
        '<div id="mision-feedback" aria-live="polite"></div>';

      this.bindEvents();
    },

    bindEvents: function () {
      var self = this;
      this.container.querySelectorAll('.ia-option-btn').forEach(function (btn) {
        btn.addEventListener('click', function () {
          self.selectedOption = parseInt(btn.getAttribute('data-opt-index'), 10);
          self.currentStepSolved = false;
          self.leoMood = 'descubrimiento';
          self.coachMsg = 'Opción seleccionada. Pulsa COMPROBAR para verificar tu respuesta.';
          self.render();
        });
      });

      var btnComprobar = document.getElementById('btn-mision-comprobar');
      if (btnComprobar) {
        btnComprobar.addEventListener('click', function () { self.comprobar(); });
      }

      var btnReintentar = document.getElementById('btn-mision-reintentar');
      if (btnReintentar) {
        btnReintentar.addEventListener('click', function () { self.reiniciar(); });
      }

      var btnSiguiente = document.getElementById('btn-mision-siguiente');
      if (btnSiguiente) {
        btnSiguiente.addEventListener('click', function () {
          if (!self.currentStepSolved) return;
          if (self.currentStep < self.challenges.length - 1) {
            self.currentStep += 1;
            self.selectedOption = null;
            self.currentStepSolved = false;
            self.leoMood = 'descubrimiento';
            self.coachMsg = '¡Avanzas al siguiente reto! Observa la nueva situación y elige tu respuesta.';
            self.render();
          } else {
            self.finishedAll = true;
            self.render();
          }
        });
      }
    },

    comprobar: function () {
      var ch = this.challenges[this.currentStep];
      if (this.selectedOption === null) {
        this.leoMood = 'error';
        this.coachMsg = 'Selecciona una máquina simple antes de pulsar COMPROBAR.';
        this.render();
        var fbEmpty = document.getElementById('mision-feedback');
        if (fbEmpty) fbEmpty.innerHTML = '<div class="ia-feedback-box is-error">Elige una de las tres opciones antes de comprobar.</div>';
        return;
      }

      var chosen = ch.options[this.selectedOption];
      if (chosen && chosen.correct) {
        this.currentStepSolved = true;
        AppState.awardStar(ch.id);
        this.leoMood = 'exito';
        this.coachMsg = '¡Respuesta correcta! Ya puedes avanzar al siguiente reto.';
        this.render();
        var fbOk = document.getElementById('mision-feedback');
        if (fbOk) fbOk.innerHTML = '<div class="ia-feedback-box is-success">⭐ ' + ch.successMsg + '</div>';
      } else {
        this.currentStepSolved = false;
        this.leoMood = 'error';
        this.coachMsg = 'No es ese mecanismo. ¡Observa los detalles de la imagen y vuelve a intentarlo!';
        this.render();
        var fbErr = document.getElementById('mision-feedback');
        if (fbErr) fbErr.innerHTML = '<div class="ia-feedback-box is-error">' + ch.errorMsg + '</div>';
      }
    },

    reiniciar: function () {
      this.selectedOption = null;
      this.currentStepSolved = false;
      this.leoMood = 'descubrimiento';
      this.coachMsg = 'Reto reiniciado. Selecciona un mecanismo y pulsa COMPROBAR.';
      this.render();
    }
  };

  /* ==========================================================================
     PÁGINA 6: MISIÓN CUMPLIDA (RECOMPENSAS, ESTRELLAS Y REINICIO)
     ========================================================================== */
  var PantallaFinalExperto = {
    init: function () {
      var panel = document.getElementById('ia-final-summary');
      if (!panel) return;

      var totalStars = AppState.getStarCount();
      var bPalancas = !!AppState.data.badges.palancas;
      var bPoleas = !!AppState.data.badges.poleas;
      var bEngranajes = !!AppState.data.badges.engranajes;
      var missionScore = AppState.data.finalMissionScore || 0;

      var starsEl = document.getElementById('ia-final-stars-total');
      if (starsEl) {
        starsEl.textContent = totalStars + ' de 12 estrellas obtenidas en el taller';
      }

      var missionEl = document.getElementById('ia-final-mission-status');
      if (missionEl) {
        missionEl.textContent = missionScore === 3
          ? '¡Increíble! Has superado los 3 retos de la Misión Final y salvado el taller.'
          : 'Estrellas de la Misión Final: ' + missionScore + ' de 3.';
      }

      this.updateBadgeCard('card-badge-palancas', bPalancas);
      this.updateBadgeCard('card-badge-poleas', bPoleas);
      this.updateBadgeCard('card-badge-engranajes', bEngranajes);

      var btnResetPlay = document.getElementById('btn-volver-a-jugar');
      if (btnResetPlay && btnResetPlay.getAttribute('data-ia-bound') !== '1') {
        btnResetPlay.setAttribute('data-ia-bound', '1');
        btnResetPlay.addEventListener('click', function () {
          AppState.resetAll();
          var isRoot = window.location.pathname.indexOf('/html/') === -1 && window.location.pathname.indexOf('\\html\\') === -1;
          window.location.href = isRoot ? 'index.html' : '../index.html';
        });
      }
    },

    updateBadgeCard: function (id, unlocked) {
      var card = document.getElementById(id);
      if (!card) return;
      card.classList.toggle('is-earned', unlocked);
      var status = card.querySelector('.ia-reward-status');
      if (status) {
        status.textContent = unlocked ? '¡Insignia desbloqueada!' : 'Supera los 3 retos del nivel para ganarla';
      }
    }
  };

  /* ==========================================================================
     INICIALIZACIÓN UNIVERSAL Y OBSERVADOR DE RE-RENDERIZADO DE EXELEARNING
     ========================================================================== */
  function bootAll() {
    AppState.load();
    ControladorAudio.init();
    ControladorInicio.init();
    JuegoPalancas.init();
    JuegoPoleas.init();
    JuegoEngranajes.init();
    GranMisionFinal.init();
    PantallaFinalExperto.init();
  }

  window.InventoresApp = {
    bootAll: bootAll,
    AppState: AppState,
    ControladorAudio: ControladorAudio,
    JuegoPalancas: JuegoPalancas,
    JuegoPoleas: JuegoPoleas,
    JuegoEngranajes: JuegoEngranajes,
    GranMisionFinal: GranMisionFinal,
    PantallaFinalExperto: PantallaFinalExperto
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', bootAll);
  } else {
    bootAll();
  }

  window.addEventListener('load', function () {
    setTimeout(bootAll, 120);
    setTimeout(bootAll, 450);
  });
})();

</script>","textTextarea":"<div class="ia-taller-wrap">
