{"ideviceId":"idv-n2-3","textInfoDurationInput":"","textInfoDurationTextInput":"Duración","textInfoParticipantsInput":"","textInfoParticipantsTextInput":"Agrupamiento","textarea":"<div class="ia-taller-wrap">
