}

.ia-brand {
 display: flex;
 flex-direction: column;
}

.ia-brand-title {
 font-size: 1.25rem;
 font-weight: 900;
 color: var(--ia-amarillo);
 letter-spacing: 0.5px;
 line-height: 1.2;
}

.ia-brand-subtitle {
 font-size: 0.94rem;
 color: #E5F7F5;
 font-weight: 700;
}

.ia-progress-summary {
