 flex-wrap: wrap;
 align-items: center;
 gap: 10px;
}

.ia-star-pill {
 background: var(--ia-amarillo);
 color: var(--ia-petroleo-dark);
 font-weight: 900;
 font-size: 1.05rem;
 padding: 7px 16px;
 border-radius: 999px;
 border: 2.5px solid var(--ia-blanco);
 display: inline-flex;
 align-items: center;
 gap: 6px;
 box-shadow: 0 3px 0 rgba(0, 0, 0, 0.2);
}

.ia-badges-mini {
 display: inline-flex;
 flex-wrap: wrap;
 gap: 6px;
}

.ia-badge-chip {
 font-size: 0.82rem;
 font-weight: 800;
 padding: 5px 11px;
 border-radius: 999px;
 background: rgba(255, 255, 255, 0.12);
 color: #D9E8F5;
 border: 2px dashed rgba(255, 255, 255, 0.35);
}

.ia-badge-chip.is-unlocked {
 background: var(--ia-turquesa);
 color: var(--ia-petroleo-dark);
