}

/* Escenarios de historia y lectura del taller */
.ia-card {
 background: var(--ia-blanco);
 border: 3.5px solid var(--ia-petroleo);
 border-radius: 24px;
 padding: 26px 30px;
 margin-bottom: 26px;
 box-shadow: 0 10px 0 rgba(23, 59, 87, 0.14);
 position: relative;
}

.ia-card--highlight {
 border-color: var(--ia-naranja);
 background: linear-gradient(180deg, #FFFFFF 0%, #FFFDF7 100%);
}

/* Etiqueta de estación / personaje secundario */
.ia-station-banner {
 display: inline-flex;
 align-items: center;
 gap: 10px;
 background: var(--ia-petroleo);
 color: var(--ia-amarillo);
 font-weight: 900;
 font-size: 0.95rem;
 padding: 6px 16px;
 border-radius: 999px;
 border: 2px solid var(--ia-turquesa);
 margin-bottom: 12px;
}

.ia-page-title {
 color: var(--ia-petroleo);
 font-size: 2.05rem;
 font-weight: 900;
 margin: 0 0 12px;
 line-height: 1.2;
}

.ia-section-title {
 color: var(--ia-petroleo);
 font-size: 1.45rem;
 font-weight: 900;
 margin: 0 0 12px;
 display: flex;
 align-items: center;
 gap: 10px;
}

.ia-lead-text {
 font-size: 1.2rem;
 font-weight: 700;
 color: var(--ia-texto);
 margin: 0 0 14px;
}

.ia-question-call {
 font-size: 1.35rem;
 font-weight: 900;
 color: var(--ia-naranja);
 margin: 12px 0 18px;
}

/* Marco escénico de ilustraciones */
.ia-illustration-box {
 background: linear-gradient(180deg, var(--ia-crema) 0%, var(--ia-crema-warm) 100%);
 border: 3.5px solid var(--ia-petroleo);
 border-radius: 20px;
 padding: 14px;
 margin: 16px 0 20px;
 text-align: center;
 box-shadow: inset 0 2px 6px rgba(23, 59, 87, 0.08);
}

.ia-illustration-box img {
 max-width: 100%;
 height: auto;
 border-radius: 14px;
 display: block;
 margin: 0 auto;
}

/* Tarjetas comparativas de conceptos */
.ia-concept-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(270px, 1fr));
 gap: 18px;
 margin-top: 16px;
}

.ia-concept-item {
 background: var(--ia-crema);
 border: 3px solid var(--ia-turquesa);
 border-left: 8px solid var(--ia-petroleo);
 border-radius: 16px;
 padding: 16px 20px;
}

.ia-concept-item strong {
