 font-size: 1.18rem;
 display: block;
 margin-bottom: 4px;
}

/* ==========================================================================
 BARRA DE AUDIO ACCESIBLE CON VERIFICACIÓN DE VOZ EN ESPAÑOL
 ========================================================================== */
.ia-audio-bar {
 background: linear-gradient(90deg, var(--ia-turquesa-soft) 0%, var(--ia-crema) 100%);
 border: 3px solid var(--ia-turquesa);
 border-radius: 18px;
 padding: 14px 18px;
 margin: 16px 0;
}

.ia-audio-header {
 display: flex;
 flex-wrap: wrap;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
}

.ia-audio-label {
