      <circle cx="292" cy="122" r="58" fill="#39B8AE" stroke="#173B57" stroke-width="6" stroke-dasharray="16,8"/>
      <circle cx="292" cy="122" r="16" fill="#FFF8E9" stroke="#173B57" stroke-width="3.5"/>
      <text x="292" y="210" text-anchor="middle" fill="#173B57" font-family="sans-serif" font-size="14" font-weight="bold">1. MOTOR (Derecha ↻)</text>
      <circle cx="418" cy="122" r="58" fill="#F28C45" stroke="#173B57" stroke-width="6" stroke-dasharray="16,8"/>
