 box-shadow: 0 8px 0 rgba(23, 59, 87, 0.14);
}

@media (max-width: 680px) {
 .ia-page-title {
 font-size: 1.6rem;
 }
 .ia-card,
 .ia-game-box {
 padding: 16px;
 }
 .ia-btn {
 width: 100%;
 }
